{
  "eligible": true,
  "main_quote": "\"Business Day\" means Monday through Friday of each week, excluding banking holidays.",
  "dependency_quotes": [
    "\"Business Day\" shall have the meaning given to such term in the Tariff."
  ],
  "reason": "The Tariff supplies the definition incorporated by the Agreement. It supports determinate applications and six diverse meaning questions: (1) Does an ordinary Monday qualify? Yes. (2) Does a Friday that is a banking holiday qualify? No. (3) Can a Saturday qualify if banks are open? No. (4) Does a Sunday that is not a banking holiday qualify? No. (5) Which days qualify in a Monday–Friday interval with Wednesday stipulated to be a banking holiday and no other holidays? Monday, Tuesday, Thursday and Friday. (6) Does the Agreement use a separate Business Day definition from the Tariff? No. No essential referenced definition is missing, but 'banking holidays' is not defined, so classification of disputed actual holidays requires additional information.",
  "scope_restrictions": [
    "Limited to the meaning and calendar-day membership of Business Day and the Agreement's incorporation of the Tariff definition.",
    "For date-specific applications, banking-holiday status must be stipulated or independently established; the text does not specify a banking-holiday calendar or jurisdiction.",
    "Do not infer business hours, time-of-day cutoffs, deadline-counting conventions, notice effectiveness, or operational rights and obligations from this definition."
  ]
}

{
  "eligible": true,
  "main_quote": "(t) \"Copyrights\" means copyrights (whether registered or unregistered) including applications for copyright (excluding, for clarity, Trademarks).",
  "dependency_quotes": [
    "(gg) \"Trademarks\" means any trademarks, service marks, trade names, trade dress, and other similar designations of source or origin, and registrations and applications for any of the foregoing."
  ],
  "reason": "The definition and the disclosed definition of its express exclusion support determinate membership decisions. No essential referenced definition is missing. Six diverse meaning questions are answerable within this scope: (1) Are registered copyrights included? Yes. (2) Are unregistered copyrights included? Yes. (3) Are applications for copyright included? Yes. (4) Are service marks included? No; they are Trademarks. (5) Are trade names and trade dress included? No; they are Trademarks. (6) Are registrations and applications for source-or-origin designations included? No; they fall within the Trademarks exclusion.",
  "scope_restrictions": [
    "Limited to the meaning and membership scope of Copyrights, including registration status, copyright applications, and the express Trademarks exclusion.",
    "Does not determine whether a particular work qualifies for copyright protection under applicable law or resolve overlapping copyright and trademark protection in a particular asset.",
    "Does not determine ownership, assignment, membership in narrower assigned or licensed copyright categories, license permissions, duration, obligations, or termination consequences."
  ]
}

{
  "eligible": true,
  "main_quote": "As used in this Agreement, the term \"Force Majeure\" means any act of God, strike, lock out or other industrial disturbance, terrorist act, war (declared or undeclared), riot, epidemic, fire or other catastrophe, or act of any government. However, your inability to obtain financing or make payments (regardless of the reason) does not constitute \"Force Majeure.\"",
  "dependency_quotes": [
    "\"You\" and \"your\" refers to the Franchisee."
  ],
  "reason": "The definition supplies determinate included events and an express exclusion, with no missing essential referenced definition. It supports at least six diverse meaning questions: (1) Is a strike included? (2) Must a war be declared to qualify? (3) Is an epidemic included? (4) Are governmental acts included? (5) Is the list limited to natural events? (6) Does the Franchisee's inability to obtain financing or make payments qualify if caused by an otherwise listed event? The disclosed language answers these questions without importing the operational requirements for contractual relief.",
  "scope_restrictions": [
    "Limited to the meaning and membership scope of Force Majeure, not entitlement to relief, performance excuses, notice requirements, mitigation duties, or remedies.",
    "The financing and payment exclusion applies to the Franchisee's inability regardless of its cause; distinguish that inability from an underlying event separately listed in the definition.",
    "The source does not further define act of God, other industrial disturbance, or other catastrophe; disputed boundary cases cannot be resolved conclusively from this definition alone."
  ]
}
